//! Build29683 name validation and bounded classic-DACL admission.
use crate::user::windows::registry::Value;
use std::collections::BTreeMap;
use std::io;
use std::sync::Arc;

const XOR_KEY: u64 = 0x41C6_4E6D_A3BC_0074;

#[derive(Debug, Clone, Copy)]
pub(crate) struct Name {
    pub(crate) lifetime: u8,
    pub(crate) scope: u8,
}
impl Name {
    pub(crate) fn decode(value: u64) -> Option<Self> {
        let bits = value ^ XOR_KEY;
        let scope = ((bits >> 6) & 15) as u8;
        let persistent = bits & 0x400 != 0;
        if bits & 15 != 1 || scope > 5 || (persistent && !matches!(scope, 0 | 2 | 4)) {
            return None;
        }
        Some(Self {
            lifetime: ((bits >> 4) & 3) as u8,
            scope,
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct Group {
    pub(crate) sid: Vec<u8>,
    pub(crate) attributes: u32,
}
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct Subject {
    pub(crate) user: Vec<u8>,
    pub(crate) groups: Vec<Group>,
    pub(crate) restricted: Vec<Group>,
    pub(crate) app_container: bool,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum Permission {
    Missing,
    Denied,
    Unmodeled,
    Allowed,
}
#[derive(Debug, Clone, Default)]
pub(crate) struct Catalog {
    records: Arc<BTreeMap<u64, Option<u32>>>,
    primary_app_container: Option<bool>,
}
fn invalid(message: &'static str) -> io::Error {
    io::Error::new(io::ErrorKind::InvalidData, message)
}
fn u16le(bytes: &[u8], at: usize) -> Option<u16> {
    Some(u16::from_le_bytes(bytes.get(at..at + 2)?.try_into().ok()?))
}
fn u32le(bytes: &[u8], at: usize) -> Option<u32> {
    Some(u32::from_le_bytes(bytes.get(at..at + 4)?.try_into().ok()?))
}
pub(super) fn sid(bytes: &[u8]) -> Option<&[u8]> {
    if bytes.first() != Some(&1) || *bytes.get(1)? > 15 {
        return None;
    }
    bytes.get(..8 + usize::from(bytes[1]) * 4)
}
fn matches(subject: &Subject, candidate: &[u8], deny: bool, restricted: bool) -> bool {
    if !restricted && subject.user == candidate {
        return true;
    }
    let groups = if restricted {
        &subject.restricted
    } else {
        &subject.groups
    };
    groups.iter().any(|group| {
        group.sid == candidate
            && if deny {
                group.attributes & (4 | 16) != 0
            } else {
                group.attributes & 4 != 0 && group.attributes & 16 == 0
            }
    })
}
fn grants(sd: &[u8], subject: &Subject) -> Option<u32> {
    // This profile admits an absent owner/group/SACL and classic, noninherited
    // allow/deny ACEs. Conditional/object ACEs, labels, AppContainers and other
    // descriptor controls remain explicit unmodeled inputs, never grant-all.
    if subject.app_container
        || !subject.restricted.is_empty()
        || sd.len() < 28
        || sd[0] != 1
        || sd[1] != 0
        || u16le(sd, 2)? != 0x8004
        || (4..16).any(|at| sd[at] != 0)
        || u32le(sd, 16)? != 20
    {
        return None;
    }
    let acl = &sd[20..];
    if !matches!(acl[0], 2 | 4)
        || acl[1] != 0
        || u16le(acl, 2)? as usize != acl.len()
        || u16le(acl, 6)? != 0
    {
        return None;
    }
    let mut entries = Vec::new();
    let mut at = 8;
    for _ in 0..u16le(acl, 4)? {
        let kind = *acl.get(at)?;
        let size = u16le(acl, at + 2)? as usize;
        if !matches!(kind, 0 | 1) || *acl.get(at + 1)? != 0 || size < 16 || size % 4 != 0 {
            return None;
        }
        let ace = acl.get(at..at.checked_add(size)?)?;
        let mask = u32le(ace, 4)?;
        let candidate = sid(&ace[8..])?;
        if candidate.len() + 8 != ace.len() {
            return None;
        }
        if mask & !3 != 0 && matches(subject, candidate, kind == 1, false) {
            return None;
        }
        entries.push((kind, mask, candidate));
        at += size;
    }
    if at != acl.len() {
        return None;
    }
    let allowed = |bit: u32, restricted: bool| {
        for &(kind, mask, candidate) in &entries {
            if mask & bit != 0 && matches(subject, candidate, kind == 1, restricted) {
                return kind == 0;
            }
        }
        false
    };
    Some(
        [1, 2]
            .into_iter()
            .filter(|&bit| {
                allowed(bit, false) && (subject.restricted.is_empty() || allowed(bit, true))
            })
            .fold(0, |mask, bit| mask | bit),
    )
}
impl Catalog {
    /// O(V log V + A*S) time and O(V) retained records; V<=4096 values,
    /// A total ACE count, S captured token SID count. No host pointer is retained.
    pub(crate) fn selected(values: Vec<Value>, subject: Subject) -> io::Result<Self> {
        if values.len() > 4096
            || sid(&subject.user) != Some(subject.user.as_slice())
            || subject
                .groups
                .iter()
                .chain(&subject.restricted)
                .any(|g| sid(&g.sid) != Some(g.sid.as_slice()))
        {
            return Err(invalid("WNF catalog/subject exceeds its bounded schema"));
        }
        let mut records = BTreeMap::new();
        for value in values {
            if value.kind != 3 || value.name.len() != 16 || value.data.len() < 4 {
                return Err(invalid(
                    "installed WNF value is not a named binary descriptor",
                ));
            }
            let name = value
                .name
                .iter()
                .try_fold(0u64, |n, &unit| {
                    char::from_u32(u32::from(unit))?
                        .to_digit(16)
                        .map(|digit| (n << 4) | u64::from(digit))
                })
                .ok_or_else(|| invalid("installed WNF name is not 16 hexadecimal units"))?;
            let parsed =
                Name::decode(name).ok_or_else(|| invalid("installed WNF name is malformed"))?;
            if parsed.lifetime != 0 || records.contains_key(&name) {
                return Err(invalid(
                    "installed WNF catalog is duplicate or not well-known",
                ));
            }
            let length = value.data.len();
            let maximum = u32le(&value.data, length - 4).unwrap();
            let grant = if parsed.scope == 3 && maximum <= 4096 {
                grants(&value.data[..length - 4], &subject)
            } else {
                None
            };
            records.insert(name, grant);
        }
        // A publish-only grant is not represented by the recorded provisioned
        // process catalog. Its mask conversion remains unmodeled rather than
        // applying an unverified access requirement.
        for grant in records.values_mut() {
            if *grant == Some(2) {
                *grant = None;
            }
        }
        Ok(Self {
            records: Arc::new(records),
            primary_app_container: Some(subject.app_container),
        })
    }
    /// Retains the same validated primary-token property used for WNF grants.
    /// `None` is an absent snapshot, not a non-AppContainer token.
    pub(crate) fn primary_app_container(&self) -> Option<bool> {
        self.primary_app_container
    }
    pub(crate) fn permission(&self, name: u64, event_mask: u32) -> Permission {
        let Some(grant) = self.records.get(&name) else {
            return Permission::Missing;
        };
        let Some(grant) = grant else {
            return Permission::Unmodeled;
        };
        let required = if event_mask == 0 {
            0
        } else if event_mask & 0x0E != 0 {
            3
        } else {
            1
        };
        if grant & required == required {
            Permission::Allowed
        } else {
            Permission::Denied
        }
    }
}

use super::catalog::*;
use crate::user::windows::registry::Value;
use std::collections::HashMap;
use std::sync::OnceLock;

const REGISTRY: &str = include_str!(
    "../../../../docs/specifications/windows/native-wnf-subscribe/native-wnf-subscribe-registry.json"
);
const SUBJECT: &str = include_str!(
    "../../../../docs/specifications/windows/native-wnf-subscribe/native-wnf-subscribe-subject-arm64.log"
);
pub(crate) fn hex(text: &str) -> Vec<u8> {
    assert!(text.len().is_multiple_of(2));
    text.as_bytes()
        .chunks_exact(2)
        .map(|chunk| u8::from_str_radix(std::str::from_utf8(chunk).unwrap(), 16).unwrap())
        .collect()
}
pub(crate) fn rows(text: &str) -> Vec<HashMap<&str, &str>> {
    text.lines()
        .filter(|line| line.starts_with("case=") || line.contains("-case="))
        .map(|line| {
            line.split_whitespace()
                .map(|field| field.split_once('=').unwrap())
                .collect()
        })
        .collect()
}
fn subject() -> Subject {
    let mut subject = Subject {
        user: Vec::new(),
        groups: Vec::new(),
        restricted: Vec::new(),
        app_container: false,
    };
    for line in SUBJECT.lines().filter(|line| line.starts_with("sid ")) {
        let row: HashMap<_, _> = line
            .split_whitespace()
            .skip(1)
            .map(|field| field.split_once('=').unwrap())
            .collect();
        let group = Group {
            sid: hex(row["bytes"]),
            attributes: u32::from_str_radix(row["attributes"], 16).unwrap(),
        };
        match row["kind"] {
            "user" => subject.user = group.sid,
            "group" => subject.groups.push(group),
            "restricted" => subject.restricted.push(group),
            _ => panic!("unknown native token record"),
        }
    }
    assert!(SUBJECT.contains("app-container=0"));
    assert!(SUBJECT.contains("handles-before=59 handles-after=59"));
    subject
}

pub(crate) fn empty_subject_catalog(app_container: bool) -> Catalog {
    let mut selected = subject();
    selected.app_container = app_container;
    Catalog::selected(Vec::new(), selected).unwrap()
}

#[test]
fn primary_token_property_is_retained_independently_of_catalog_records() {
    assert_eq!(Catalog::default().primary_app_container(), None);
    for flag in [false, true] {
        let catalog = empty_subject_catalog(flag);
        assert_eq!(catalog.primary_app_container(), Some(flag));
        assert_eq!(catalog.clone().primary_app_container(), Some(flag));
    }
}
pub(crate) fn values() -> Vec<Value> {
    let json: serde_json::Value =
        serde_json::from_str(REGISTRY.trim_start_matches('\u{feff}')).unwrap();
    let values = json.as_array().unwrap();
    assert_eq!(values.len(), 1613);
    values
        .iter()
        .map(|value| {
            assert_eq!(value["kind"], "Binary");
            Value {
                name: value["name"].as_str().unwrap().encode_utf16().collect(),
                kind: 3,
                data: hex(value["data"].as_str().unwrap()),
            }
        })
        .collect()
}
pub(crate) fn catalog() -> Catalog {
    static CATALOG: OnceLock<Catalog> = OnceLock::new();
    CATALOG
        .get_or_init(|| Catalog::selected(values(), subject()).unwrap())
        .clone()
}

#[test]
fn native_wnf_subscription_name_capture_replays_all_8192_domain_rows() {
    for text in [
        include_str!(
            "../../../../docs/specifications/windows/native-wnf-subscribe/native-wnf-subscribe-domain-arm64.log"
        ),
        include_str!(
            "../../../../docs/specifications/windows/native-wnf-subscribe/native-wnf-subscribe-domain-x64.log"
        ),
        include_str!(
            "../../../../docs/specifications/windows/native-wnf-subscribe/native-wnf-subscribe-domain-x86.log"
        ),
        include_str!(
            "../../../../docs/specifications/windows/native-wnf-subscribe/native-wnf-subscribe-domain-x86-laa.log"
        ),
    ] {
        assert!(text.contains("complete cases=2048"));
        let observed = rows(text);
        assert_eq!(observed.len(), 2048);
        for row in observed {
            let name = u64::from_str_radix(row["name"], 16).unwrap();
            assert_eq!(
                Name::decode(name).is_none(),
                row["status"] == "C000000D",
                "{row:?}"
            );
        }
    }
}
#[test]
fn native_wnf_subscription_catalog_access_matches_all_72_process_name_calls() {
    let text = include_str!(
        "../../../../docs/specifications/windows/native-wnf-subscribe/native-wnf-subscribe-process-names-arm64.log"
    );
    assert!(text.contains("complete names=9 data-pairs=72"));
    let catalog = catalog();
    let mut count = 0;
    for line in text.lines().filter(|line| line.starts_with("data-after ")) {
        let row: HashMap<_, _> = line
            .split_whitespace()
            .skip(1)
            .map(|field| field.split_once('=').unwrap())
            .collect();
        let name = u64::from_str_radix(row["name"], 16).unwrap();
        let mask = u32::from_str_radix(row["mask"], 16).unwrap();
        assert_eq!(
            catalog.permission(name, mask),
            match row["subscribed"] {
                "00000000" => Permission::Allowed,
                "C0000022" => Permission::Denied,
                _ => panic!("unrecognized native status"),
            },
            "{row:?}"
        );
        count += 1;
    }
    assert_eq!(count, 72);
}
#[test]
fn native_wnf_subscription_catalog_rejects_unmodeled_security_and_malformed_values() {
    let known = 0x41911A28A3BC10B5;
    let mut value = values()
        .into_iter()
        .find(|v| v.name == "41911A28A3BC10B5".encode_utf16().collect::<Vec<_>>())
        .unwrap();
    for at in [0, 2, 4, 8, 12, 16, 20, 21, 22, 26, 28, 29, 30, 32, 36, 37] {
        let mut corrupted = value.clone();
        corrupted.data[at] ^= 0x80;
        let c = Catalog::selected(vec![corrupted], subject()).unwrap();
        assert_eq!(
            c.permission(known, 0x11),
            Permission::Unmodeled,
            "byte {at}"
        );
    }
    let mut app = subject();
    app.app_container = true;
    assert_eq!(
        Catalog::selected(vec![value.clone()], app)
            .unwrap()
            .permission(known, 0),
        Permission::Unmodeled
    );
    let mut restricted = subject();
    restricted.restricted.push(restricted.groups[0].clone());
    assert_eq!(
        Catalog::selected(vec![value.clone()], restricted)
            .unwrap()
            .permission(known, 0),
        Permission::Unmodeled
    );
    assert!(Catalog::selected(vec![value.clone(), value.clone()], subject()).is_err());
    value.kind = 1;
    assert!(Catalog::selected(vec![value], subject()).is_err());
    assert_eq!(
        catalog().permission(known ^ 0x800, 0x11),
        Permission::Missing
    );
    assert_eq!(
        catalog().permission(0x41911A28A3BC0875, 0x11),
        Permission::Unmodeled
    );
}

//! Kernel objects and the process handle table.
//!
//! Objects are reference-counted by the handles that name them (and by
//! internal references such as a thread's own object). Handle values are
//! multiples of 4 allocated lowest-first from 4, and the low two bits of a
//! handle are ignored on lookup (they are tag bits on Windows). The
//! pseudo-handles `GetCurrentProcess()` (-1) and `GetCurrentThread()` (-2)
//! are not table entries; callers resolve them.
//!
//! Named objects share a process-local model of session/global namespaces.
//! Names are case-sensitive; Local aliases the default session namespace,
//! while Global is distinct. Cross-process/private namespaces are unsupported.

use std::collections::{BTreeMap, HashMap};
use std::path::PathBuf;
use std::time::Instant;

mod directory;
mod etw;
mod lpc;
pub use lpc::LpcPort;
mod scheduler;
pub use scheduler::SchedulerData;
mod wait_packets;
mod wnf;
pub use wait_packets::CompletionPacket;

/// An object identifier.
pub type ObjId = u32;

/// `GetCurrentProcess()`.
pub const CURRENT_PROCESS: u64 = u64::MAX;
/// `GetCurrentThread()`.
pub const CURRENT_THREAD: u64 = u64::MAX - 1;

/// Which host standard stream a console handle uses.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StdStream {
    /// Standard input.
    In,
    /// Standard output.
    Out,
    /// Standard error.
    Err,
}

/// An open file.
#[derive(Debug)]
pub struct FileObj {
    /// The host file (`None` for a directory handle).
    pub host: Option<std::fs::File>,
    /// Host path.
    pub host_path: PathBuf,
    /// Windows path.
    pub path: String,
    /// Granted `GENERIC_*`/`FILE_*` access mask.
    pub access: u32,
    /// Granted file sharing mask.
    pub share: u32,
    /// Shared file identity and deferred-deletion lifetime.
    pub lifetime: std::sync::Arc<crate::user::windows::fs::FileLifetime>,
    /// A CreateFile handle to the NUL device.
    pub null: bool,
    /// Opened with `FILE_APPEND_DATA` only: writes go to the end.
    pub append: bool,
    /// `FILE_FLAG_DELETE_ON_CLOSE`.
    pub delete_on_close: bool,
    /// A directory handle.
    pub directory: bool,
    /// `FILE_FLAG_OVERLAPPED`.
    pub overlapped: bool,
}

/// A kernel object.
#[derive(Debug)]
pub enum Object {
    /// A file or directory.
    File(FileObj),
    /// A console standard stream (the host's stdin, stdout, or stderr).
    Console(StdStream),
    /// The `NUL` device.
    Null,
    /// An event.
    Event {
        /// Manual-reset.
        manual: bool,
        /// Native signal state (LONG): zero is nonsignaled. NtCreateEvent
        /// retains the low BOOLEAN byte, including noncanonical 2..=255.
        signaled: i32,
    },
    /// A mutex (mutant).
    Mutex {
        /// Owning thread.
        owner: Option<u32>,
        /// Recursion count.
        count: u32,
        /// The owner ended without releasing it.
        abandoned: bool,
    },
    /// A semaphore.
    Semaphore {
        /// Current count.
        count: i32,
        /// Maximum count.
        max: i32,
    },
    /// A thread.
    Thread {
        /// Thread id.
        tid: u32,
        /// Exit code once it has ended.
        exit_code: Option<u32>,
    },
    /// A process.
    Process {
        /// Process id.
        pid: u32,
        /// Exit code once it has ended.
        exit_code: Option<u32>,
    },
    /// A waitable timer.
    Timer {
        /// Manual-reset (notification) timer.
        manual: bool,
        /// Signaled.
        signaled: bool,
        /// When it next fires.
        due: Option<Instant>,
        /// Period in milliseconds (0 = one-shot).
        period_ms: u32,
    },
    /// A dormant extended NT timer, distinct from the legacy Timer object.
    IrTimer {
        /// Raw validated TIMER2 attributes, including notification/resolution.
        attributes: u32,
        /// Captured IR timer role, present only with TIMER2_ATTRIBUTE_IR_TIMER.
        timer_id: Option<u32>,
        /// Constructor starts unsignaled; arming belongs to timer services.
        signaled: bool,
    },
    /// A file mapping (section).
    Mapping {
        /// Backing file, if any.
        file: Option<ObjId>,
        /// Maximum size in bytes.
        size: u64,
        /// Page protection.
        protect: u32,
        /// Native SEC_* allocation attributes of this section.
        attributes: u32,
        /// Contents of a pagefile-backed mapping, shared by its views.
        shared: Option<std::sync::Arc<crate::user::mm::SharedObject>>,
    },
    /// An anonymous pipe end.
    Pipe {
        /// Shared buffer id.
        pipe: u32,
        /// The write end.
        write: bool,
    },
    /// An I/O completion port.
    CompletionPort {
        /// Native-width completion payloads, in delivery order.
        queue: std::collections::VecDeque<CompletionPacket>,
        /// Effective runnable-thread limit; zero requests the guest CPU count.
        /// Construction records it; completion dequeue must enforce it.
        concurrency: u32,
    },
    /// An emulated LPC communication endpoint with an owned local section view.
    LpcPort(LpcPort),
    /// An NT wait packet. A new packet is notification-signaled: object waits
    /// do not consume its state. Association services own later transitions.
    WaitCompletionPacket {
        /// Packet signal state, shared by every duplicate guest handle.
        signaled: bool,
    },
    /// A dormant NT thread-pool worker factory. Activation/packet scheduling
    /// belongs to the worker-factory services, not to construction.
    WorkerFactory {
        /// Owned completion-port reference, independent of its caller handle.
        port: ObjId,
        /// Owned explicit process-object reference, if a real handle was used.
        process: Option<ObjId>,
        /// Target guest process identity; pseudo handles refer to this process.
        pid: u32,
        /// Worker entry address, not dereferenced by the constructor.
        start: u64,
        /// Worker entry parameter.
        parameter: u64,
        /// Unsigned maximum; zero is retained, not expanded to the CPU count.
        maximum: u32,
        /// Last successfully captured class14 soft-limit request. None means
        /// no request has been recorded; the native constructor default is
        /// unknown. This does not imply an effective active-worker limit.
        soft_maximum: Option<u32>,
        /// Measured class7 BindingCount, initially zero. Class3 zero requests
        /// set all bits; nonzero requests add a signed delta with saturation.
        binding_count: u32,
        /// Requested/default stack reserve in bytes, without creation rounding.
        reserve: u64,
        /// Requested/default stack commit in bytes.
        commit: u64,
    },
    /// A dormant process-local ETW provider registration. The private160 B
    /// request is captured verbatim; later guest writes do not change it.
    EtwRegistration {
        /// Opaque measured kernel header, including GUID and user context.
        request: Box<[u8; 160]>,
        /// Once-captured provider traits; caller writes cannot alter this blob.
        traits: Option<Box<[u8]>>,
    },
    /// A process-local scheduler-data owner, distinct from a mapped Section.
    /// Slot/data binding is a separate service; constructor handles own this
    /// identity until their final close or process object-table drain.
    SchedulerSharedData {
        /// The guest process owning the scheduler-data identity.
        pid: u32,
        /// Lazy mapped view and fixed slot occupancy.
        data: SchedulerData,
    },
    /// A private immutable runtime registry key shared by opened handles.
    Key(std::sync::Arc<super::registry::Key>),
    /// A selected immutable NT object-manager directory, independent of files.
    Directory(std::sync::Arc<super::object_namespace::Directory>),
    /// Selected installed image-section metadata, independent of native HANDLEs.
    ImageSection(std::sync::Arc<super::object_namespace::ImageSection>),
    /// Selected immutable data-section bytes and native grant metadata.
    DataSection(std::sync::Arc<super::object_namespace::DataSection>),
    /// A selected immutable NT symbolic link, shared across guest handles.
    SymbolicLink(std::sync::Arc<super::object_namespace::SymbolicLink>),
    /// This process's immutable captured primary-token subject; no host HANDLE.
    PrimaryToken,
    /// An object this implementation only needs to name (unmodeled tokens,
    /// registry keys, window stations).
    Opaque(&'static str),
}

impl Object {
    /// The object type name `NtQueryObject` reports.
    pub fn type_name(&self) -> &'static str {
        match self {
            Object::File(_) | Object::Console(_) | Object::Null => "File",
            Object::Event { .. } => "Event",
            Object::Mutex { .. } => "Mutant",
            Object::Semaphore { .. } => "Semaphore",
            Object::Thread { .. } => "Thread",
            Object::Process { .. } => "Process",
            Object::Timer { .. } => "Timer",
            Object::IrTimer { .. } => "IRTimer",
            Object::Mapping { .. } | Object::ImageSection(_) | Object::DataSection(_) => "Section",
            Object::Pipe { .. } => "File",
            Object::CompletionPort { .. } => "IoCompletion",
            Object::LpcPort(_) => "ALPC Port",
            Object::WaitCompletionPacket { .. } => "WaitCompletionPacket",
            Object::WorkerFactory { .. } => "TpWorkerFactory",
            Object::EtwRegistration { .. } => "EtwRegistration",
            Object::SchedulerSharedData { .. } => "SchedulerSharedData",
            Object::Key(_) => "Key",
            Object::Directory(_) => "Directory",
            Object::SymbolicLink(_) => "SymbolicLink",
            Object::PrimaryToken => "Token",
            Object::Opaque(t) => t,
        }
    }
}

#[derive(Debug)]
struct Entry {
    obj: Object,
    refs: u32,
    name: Option<String>,
}

#[derive(Clone, Copy, Debug)]
struct HandleEntry {
    obj: ObjId,
    access: u32,
    inherit: bool,
    protect_from_close: bool,
}

/// Objects and handles.
#[derive(Debug, Default)]
pub struct Objects {
    objs: HashMap<ObjId, Entry>,
    next: ObjId,
    handles: BTreeMap<u32, HandleEntry>,
    names: HashMap<String, ObjId>,
    packets: wait_packets::PacketAssociations,
    /// One process-owned notification Event, independent of caller handles.
    wnf_event: Option<ObjId>,
    /// ETW process notification registration is independent of WNF.
    etw_event: Option<ObjId>,
    wnf_subscriptions: wnf::Subscriptions,
    scheduler_bindings: BTreeMap<u32, (ObjId, u32)>,
    retired_scheduler_views: Vec<super::memory::SchedulerView>,
    retired_lpc_views: Vec<super::memory::SharedViewOwner>,
}

fn name_key(name: &str) -> String {
    if let Some(n) = name.strip_prefix("Global\\") {
        format!("Global\\{n}")
    } else {
        format!("Local\\{}", name.strip_prefix("Local\\").unwrap_or(name))
    }
}

impl Objects {
    /// Creates an object with no references yet.
    pub fn create(&mut self, obj: Object) -> ObjId {
        self.try_create(obj)
            .expect("internal object capacity exhausted")
    }

    /// Creates an unreferenced object, rejecting identifier exhaustion.
    pub fn try_create(&mut self, obj: Object) -> Option<ObjId> {
        let next = self.next.checked_add(1)?;
        if let Object::WorkerFactory { port, process, .. } = &obj {
            if !matches!(self.obj(*port), Some(Object::CompletionPort { .. }))
                || process.is_some_and(|id| !matches!(self.obj(id), Some(Object::Process { .. })))
            {
                return None;
            }
            // At most two references: validate every count before changing
            // either. Publication rollback and final close release them below.
            let ids = [*port, process.unwrap_or(*port)];
            self.retain_many(&ids[..if process.is_some() { 2 } else { 1 }])
                .ok()?;
        }
        self.objs.insert(
            next,
            Entry {
                obj,
                refs: 0,
                name: None,
            },
        );
        self.next = next;
        Some(next)
    }

    /// Creates a named object, or finds the existing object of that name:
    /// `(id, existed)`.
    pub fn create_named(&mut self, name: &str, obj: Object) -> (ObjId, bool) {
        self.try_create_named(name, obj)
            .expect("internal object capacity exhausted")
    }

    /// Fallible named creation. The caller must independently check the
    /// existing object's type and the requested access grant.
    pub fn try_create_named(&mut self, name: &str, obj: Object) -> Option<(ObjId, bool)> {
        let key = name_key(name);
        if let Some(&id) = self.names.get(&key) {
            return Some((id, true));
        }
        let id = self.try_create(obj)?;
        self.objs.get_mut(&id).unwrap().name = Some(key.clone());
        self.names.insert(key, id);
        Some((id, false))
    }

    /// The object named `name`.
    pub fn by_name(&self, name: &str) -> Option<ObjId> {
        self.names.get(&name_key(name)).copied()
    }

    /// Adds an internal reference.
    pub fn retain(&mut self, id: ObjId) {
        if let Some(e) = self.objs.get_mut(&id) {
            e.refs += 1;
        }
    }

    /// Pins a complete wait set transactionally. Multiplicities are counted
    /// before publishing references: O(N) expected time and O(U) space for N
    /// identifiers and U distinct objects.
    pub fn retain_many(&mut self, ids: &[ObjId]) -> Result<(), &'static str> {
        let mut counts = HashMap::<ObjId, u32>::new();
        for &id in ids {
            let n = counts.entry(id).or_default();
            *n = n
                .checked_add(1)
                .ok_or("wait reference multiplicity overflow")?;
        }
        for (&id, &count) in &counts {
            self.objs
                .get(&id)
                .ok_or("wait object disappeared")?
                .refs
                .checked_add(count)
                .ok_or("wait object reference overflow")?;
        }
        for (id, count) in counts {
            self.objs.get_mut(&id).expect("validated wait object").refs += count;
        }
        Ok(())
    }

    /// Drops a reference; the object is destroyed at zero. Returns the
    /// destroyed object.
    pub fn release(&mut self, id: ObjId) -> Option<Object> {
        let e = self.objs.get_mut(&id)?;
        e.refs = e.refs.saturating_sub(1);
        if e.refs > 0 {
            return None;
        }
        let mut e = self.objs.remove(&id)?;
        if let Some(n) = &e.name {
            self.names.remove(n);
        }
        if let Object::WorkerFactory { port, process, .. } = &e.obj {
            // These dependencies are a CompletionPort and a Process, so this
            // recursion has depth one and cannot form an object cycle.
            self.release(*port);
            if let Some(id) = process {
                self.release(*id);
            }
        }
        if matches!(e.obj, Object::WaitCompletionPacket { .. }) {
            self.forget_wait_packet(id);
        }
        self.retire_scheduler_object(&e.obj);
        self.retire_lpc_object(&mut e.obj);
        Some(e.obj)
    }

    /// Opens a handle to `id`.
    pub fn open(&mut self, id: ObjId, inherit: bool) -> u32 {
        self.open_access(id, inherit, u32::MAX)
            .expect("internal object handle capacity exhausted")
    }

    /// Opens a handle with an explicit grant. Invalid objects, reference
    /// overflow and handle exhaustion leave the table unchanged. O(H) time
    /// and O(1) extra space for H open handles.
    pub fn open_access(&mut self, id: ObjId, inherit: bool, access: u32) -> Option<u32> {
        let refs = self.objs.get(&id)?.refs.checked_add(1)?;
        let mut h = 4u32;
        for &k in self.handles.keys() {
            if k != h {
                break;
            }
            h = h.checked_add(4)?;
        }
        self.objs.get_mut(&id)?.refs = refs;
        self.handles.insert(
            h,
            HandleEntry {
                obj: id,
                access,
                inherit,
                protect_from_close: false,
            },
        );
        Some(h)
    }

    /// Creates an object and opens a handle to it.
    pub fn insert(&mut self, obj: Object) -> u32 {
        let id = self.create(obj);
        self.open(id, false)
    }

    fn key(handle: u64) -> Option<u32> {
        u32::try_from(handle & !3).ok().filter(|&h| h != 0)
    }

    /// The object a handle names.
    pub fn id(&self, handle: u64) -> Option<ObjId> {
        self.handles.get(&Self::key(handle)?).map(|e| e.obj)
    }

    /// The access mask granted to this particular handle.
    pub fn access(&self, handle: u64) -> Option<u32> {
        self.handles.get(&Self::key(handle)?).map(|e| e.access)
    }

    /// The object behind a handle.
    pub fn get(&self, handle: u64) -> Option<&Object> {
        let id = self.id(handle)?;
        self.objs.get(&id).map(|e| &e.obj)
    }

    /// Mutable access to the object behind a handle.
    pub fn get_mut(&mut self, handle: u64) -> Option<&mut Object> {
        let id = self.id(handle)?;
        self.objs.get_mut(&id).map(|e| &mut e.obj)
    }

    /// An object by id.
    pub fn obj(&self, id: ObjId) -> Option<&Object> {
        self.objs.get(&id).map(|e| &e.obj)
    }

    /// Mutable access to an object by id.
    pub fn obj_mut(&mut self, id: ObjId) -> Option<&mut Object> {
        self.objs.get_mut(&id).map(|e| &mut e.obj)
    }

    /// Closes a handle. `Err(())` for an invalid or protected handle.
    /// Returns the object if this was its last reference.
    pub fn close(&mut self, handle: u64) -> Result<Option<Object>, ()> {
        let key = Self::key(handle).ok_or(())?;
        let e = *self.handles.get(&key).ok_or(())?;
        if e.protect_from_close {
            return Err(());
        }
        self.handles.remove(&key);
        if !self.handles.values().any(|handle| handle.obj == e.obj) {
            self.retire_lpc_handle(e.obj);
            match self.obj(e.obj) {
                // An independent object wait can still pin the packet.
                Some(Object::WaitCompletionPacket { .. }) => self.forget_wait_packet(e.obj),
                // Closing the final port handle discards existing completions,
                // but pending associations can deliver to the retained port.
                Some(Object::CompletionPort { .. }) => self.discard_completion_queue(e.obj),
                _ => {}
            }
        }
        Ok(self.release(e.obj))
    }

    /// Duplicates a handle within the process.
    pub fn duplicate(&mut self, handle: u64, inherit: bool) -> Option<u32> {
        let id = self.id(handle)?;
        self.open_access(id, inherit, self.access(handle)?)
    }

    /// `HANDLE_FLAG_INHERIT` and `HANDLE_FLAG_PROTECT_FROM_CLOSE` of a
    /// handle.
    pub fn flags(&self, handle: u64) -> Option<u32> {
        let e = self.handles.get(&Self::key(handle)?)?;
        Some(u32::from(e.inherit) | u32::from(e.protect_from_close) << 1)
    }

    /// Changes a handle's flags under `mask`.
    pub fn set_flags(&mut self, handle: u64, mask: u32, flags: u32) -> bool {
        let Some(key) = Self::key(handle) else {
            return false;
        };
        let Some(e) = self.handles.get_mut(&key) else {
            return false;
        };
        if mask & 1 != 0 {
            e.inherit = flags & 1 != 0;
        }
        if mask & 2 != 0 {
            e.protect_from_close = flags & 2 != 0;
        }
        true
    }

    /// Number of open handles (`GetProcessHandleCount`).
    pub fn handle_count(&self) -> usize {
        self.handles.len()
    }

    /// Every live object, including internally pinned objects with no handle.
    pub fn iter(&self) -> impl Iterator<Item = (ObjId, &Object)> {
        self.objs.iter().map(|(&k, e)| (k, &e.obj))
    }

    /// Process termination destroys the entire local table, including protected
    /// handles and internally referenced objects. Returned objects let the
    /// caller report final file cleanup failures rather than hiding them.
    pub fn drain(&mut self) -> impl Iterator<Item = Object> + '_ {
        self.handles.clear();
        self.names.clear();
        self.packets = Default::default();
        self.wnf_event = None;
        self.etw_event = None;
        self.wnf_subscriptions.records.clear();
        self.scheduler_bindings.clear();
        // Queue all views eagerly: dropping a partially consumed Drain also
        // removes its remaining objects, without running iterator map closures.
        for entry in self.objs.values_mut() {
            if let Object::LpcPort(port) = &mut entry.obj
                && let Some(view) = port.take_view()
            {
                self.retired_lpc_views.push(view);
            }
            if let Object::SchedulerSharedData { data, .. } = &entry.obj
                && let Some(view) = &data.view
            {
                self.retired_scheduler_views.push(view.clone());
            }
        }
        self.objs.drain().map(|(_, entry)| entry.obj)
    }

    /// Every object id with its object (for the scheduler's timers).
    pub fn iter_mut(&mut self) -> impl Iterator<Item = (ObjId, &mut Object)> {
        self.objs.iter_mut().map(|(&k, e)| (k, &mut e.obj))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn handles_are_lowest_free_multiples_of_four_and_ignore_tag_bits() {
        let mut o = Objects::default();
        let a = o.insert(Object::Null);
        let b = o.insert(Object::Null);
        assert_eq!((a, b), (4, 8));
        assert!(o.get(u64::from(a) | 3).is_some(), "tag bits ignored");
        o.close(u64::from(a)).unwrap();
        assert_eq!(o.insert(Object::Null), 4, "lowest free value reused");
        assert!(o.close(0x1000).is_err());
        assert!(o.get(0).is_none());
    }

    #[test]
    fn objects_live_until_their_last_handle_closes() {
        let mut o = Objects::default();
        let h = o.insert(Object::Event {
            manual: true,
            signaled: 0,
        });
        let d = o.duplicate(u64::from(h), false).unwrap();
        assert!(o.close(u64::from(h)).unwrap().is_none());
        assert!(matches!(o.get(u64::from(d)), Some(Object::Event { .. })));
        assert!(o.close(u64::from(d)).unwrap().is_some());
    }

    #[test]
    fn names_are_exact_case_and_global_namespace_is_distinct() {
        let mut o = Objects::default();
        let (a, existed) = o.create_named("Local\\MyEvent", Object::Null);
        assert!(!existed);
        let (b, existed) = o.create_named("MyEvent", Object::Null);
        assert!(existed);
        assert_eq!(a, b);
        assert_eq!(o.by_name("myevent"), None);
        let (global, existed) = o.create_named("Global\\MyEvent", Object::Null);
        assert!(!existed);
        assert_ne!(global, a);
        assert_eq!(o.by_name("Global\\MyEvent"), Some(global));
        let h = o.open(a, false);
        o.close(u64::from(h)).unwrap();
        assert_eq!(o.by_name("MyEvent"), None, "the name goes with the object");
        assert_eq!(o.by_name("Global\\MyEvent"), Some(global));
    }

    #[test]
    fn explicit_handle_grants_are_preserved_without_escalation() {
        let mut o = Objects::default();
        assert_eq!(o.open_access(42, false, 0), None);
        let id = o.create(Object::Null);
        let a = o.open_access(id, false, 0x0010_0000).unwrap();
        let b = o.duplicate(u64::from(a), true).unwrap();
        assert_eq!(o.access(u64::from(a) | 3), Some(0x0010_0000));
        assert_eq!(o.access(u64::from(b)), Some(0x0010_0000));
        assert_eq!(o.flags(u64::from(b)), Some(1));
        let c = o.open_access(id, false, 2).unwrap();
        assert_eq!(o.access(u64::from(c)), Some(2));
        assert_eq!(o.access(u64::from(a)), Some(0x0010_0000));
        o.objs.get_mut(&id).unwrap().refs = u32::MAX;
        let before = o.handle_count();
        assert_eq!(o.open_access(id, false, 0), None);
        assert_eq!(o.handle_count(), before);
    }

    #[test]
    fn wait_pins_validate_all_objects_and_multiplicities_before_commit() {
        let mut o = Objects::default();
        let a = o.create(Object::Null);
        let b = o.create(Object::Null);
        o.retain_many(&[a, b, a]).unwrap();
        assert_eq!(o.objs[&a].refs, 2);
        assert_eq!(o.objs[&b].refs, 1);
        assert!(o.retain_many(&[a, 99]).is_err());
        assert_eq!(o.objs[&a].refs, 2);
        o.objs.get_mut(&b).unwrap().refs = u32::MAX;
        assert!(o.retain_many(&[a, b]).is_err());
        assert_eq!(o.objs[&a].refs, 2);
        o.next = u32::MAX;
        assert_eq!(o.try_create(Object::Null), None);
        assert_eq!(o.try_create_named("capacity", Object::Null), None);
        assert_eq!(o.by_name("capacity"), None);
    }

    #[test]
    fn protected_handles_cannot_be_closed() {
        let mut o = Objects::default();
        let h = o.insert(Object::Null);
        assert!(o.set_flags(u64::from(h), 2, 2));
        assert!(o.close(u64::from(h)).is_err());
        assert_eq!(o.flags(u64::from(h)), Some(2));
    }

    #[test]
    fn worker_factory_dependency_pins_are_transactional_on_capacity_and_type_failure() {
        let mut o = Objects::default();
        let port = o.create(Object::CompletionPort {
            queue: Default::default(),
            concurrency: 4,
        });
        let process = o.create(Object::Process {
            pid: 1,
            exit_code: None,
        });
        let factory = |port, process| Object::WorkerFactory {
            port,
            process: Some(process),
            pid: 1,
            start: 0,
            parameter: 0,
            maximum: 0,
            soft_maximum: None,
            binding_count: 0,
            reserve: 65536,
            commit: 4096,
        };
        let next = o.next;
        o.objs.get_mut(&process).unwrap().refs = u32::MAX;
        assert_eq!(o.try_create(factory(port, process)), None);
        assert_eq!(o.objs[&port].refs, 0);
        assert_eq!(o.objs[&process].refs, u32::MAX);
        assert_eq!(o.next, next);
        o.objs.get_mut(&process).unwrap().refs = 0;
        assert_eq!(o.try_create(factory(process, port)), None);
        assert_eq!(o.objs[&port].refs, 0);
        assert_eq!(o.objs[&process].refs, 0);
        o.next = u32::MAX;
        assert_eq!(o.try_create(factory(port, process)), None);
        assert_eq!(o.objs[&port].refs, 0);
        assert_eq!(o.objs[&process].refs, 0);
        o.next = next;
        let id = o.try_create(factory(port, process)).unwrap();
        assert_eq!(o.objs[&port].refs, 1);
        assert_eq!(o.objs[&process].refs, 1);
        assert!(matches!(o.release(id), Some(Object::WorkerFactory { .. })));
        assert_eq!(o.iter().count(), 0);
    }

    #[test]
    fn process_table_drain_removes_protected_handles_names_and_internal_refs() {
        let mut o = Objects::default();
        let (id, _) = o.create_named("drain", Object::Null);
        let handle = o.open(id, false);
        o.retain(id);
        o.set_flags(u64::from(handle), 2, 2);
        assert_eq!(o.drain().count(), 1);
        assert_eq!(o.handle_count(), 0);
        assert!(o.by_name("drain").is_none());
        assert!(o.obj(id).is_none());
    }
}

//! Blocking waits and address-keyed synchronization.
//!
//! A thread that must wait parks with a [`Wait`]; the scheduler polls
//! parked threads with [`poll`] and resumes one when its wait is satisfied,
//! times out, or (for an alertable wait) has a user APC queued. Object
//! waits follow `WaitForMultipleObjectsEx`: a wait-any wait is satisfied by
//! the lowest-indexed signaled object, a wait-all wait only when every
//! object is signaled at once; satisfying a wait consumes an auto-reset
//! event or timer, a semaphore count, or acquires a mutex (recursively for
//! its owner). A mutex whose owner ended is *abandoned*: the next acquirer
//! gets `WAIT_ABANDONED_0 + i`.
//!
//! Critical sections, SRW locks, condition variables, and `WaitOnAddress`
//! are keyed by guest address. Every built-in call is atomic with respect
//! to guest threads (all run on one host thread), so these primitives need
//! no guest-visible atomic protocol. Guest lock storage is logically opaque:
//! the synthetic encodings below are not native Windows private layouts.
//! Every transition writes guest storage transactionally before host state
//! publication. AddressSpace::write checks/materializes every page before any
//! byte write; mappings must remain stable under the serialized-process contract.

use std::collections::{HashMap, HashSet, VecDeque};
use std::time::Instant;

use super::layout::offsets;
use super::memory::{Mem, MemFault};
use super::nt::status::*;
use super::objects::{ObjId, Object};
use super::process::Proc;

mod wait_packets;
pub(crate) use wait_packets::pump_wait_packets;

/// `WAIT_ABANDONED_0`.
pub const WAIT_ABANDONED_0: u64 = 0x80;
/// `WAIT_IO_COMPLETION` (`STATUS_USER_APC`).
pub const WAIT_IO_COMPLETION: u64 = 0xC0;
/// `WAIT_TIMEOUT` (`STATUS_TIMEOUT`).
pub const WAIT_TIMEOUT: u64 = 0x102;

/// Tag separating condition-variable keys from `WaitOnAddress` keys.
pub const CONDVAR_KEY: u128 = 1 << 64;

/// Checked memory failure or fail-closed policy for invalid/undefined lock use.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SyncError {
    /// Preserve guest address and access direction.
    Fault(MemFault),
    /// Invalid ownership, storage, alignment, or arithmetic; native status unknown.
    Invalid(&'static str),
}

impl From<MemFault> for SyncError {
    fn from(value: MemFault) -> Self {
        Self::Fault(value)
    }
}

impl From<SyncError> for super::hle::ApiErr {
    fn from(value: SyncError) -> Self {
        match value {
            SyncError::Fault(fault) => Self::Fault(fault),
            SyncError::Invalid(message) => {
                Self::Internal(format!("invalid synchronization operation: {message}"))
            }
        }
    }
}

/// What a parked thread waits for.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Wait {
    /// Kernel objects (`WaitForSingleObject`, `WaitForMultipleObjects`).
    Objects {
        /// The objects.
        objs: Vec<ObjId>,
        /// Wait for all of them.
        all: bool,
        /// Timeout.
        deadline: Option<Instant>,
        /// Alertable (user APCs end the wait).
        alertable: bool,
    },
    /// A delay (`Sleep`, `SleepEx`).
    Sleep {
        /// When it ends (`None`: forever).
        deadline: Option<Instant>,
        /// Alertable.
        alertable: bool,
    },
    /// A wake on an address key (`WaitOnAddress`, condition variables).
    Address {
        /// The key.
        key: u128,
        /// Timeout.
        deadline: Option<Instant>,
    },
    /// Ownership of the critical section at `addr`.
    CritSec {
        /// The `CRITICAL_SECTION`.
        addr: u64,
    },
    /// The SRW lock at `addr`.
    Srw {
        /// The `SRWLOCK`.
        addr: u64,
        /// Exclusive (otherwise shared) mode.
        exclusive: bool,
    },
}

impl Wait {
    /// The wait's deadline.
    pub fn deadline(&self) -> Option<Instant> {
        match self {
            Wait::Objects { deadline, .. }
            | Wait::Sleep { deadline, .. }
            | Wait::Address { deadline, .. } => *deadline,
            Wait::CritSec { .. } | Wait::Srw { .. } => None,
        }
    }
}

/// An SRW lock's state.
#[derive(Clone, Debug, Default)]
struct SrwState {
    exclusive: Option<u32>,
    shared: HashSet<u32>,
    waiting_exclusive: u32,
}

/// Address-keyed synchronization state.
#[derive(Debug, Default)]
pub struct SyncState {
    /// Threads parked on each address key, in arrival order.
    waiters: HashMap<u128, VecDeque<u32>>,
    /// Threads whose address wait was woken.
    woken: HashSet<u32>,
    /// Threads parked on each critical section.
    cs_waiters: HashMap<u64, u32>,
    /// SRW locks.
    srw: HashMap<u64, SrwState>,
    /// Validated pre-retirement words left in guest storage when a normal
    /// process exit cancels other threads' exclusive waits without writing
    /// potentially obsolete lock storage. The next live lock mutation
    /// replaces the word and removes this exception.
    retired_srw_words: HashMap<u64, u64>,
    /// Explicitly initialized critical sections; use after delete is rejected.
    initialized_cs: HashSet<u64>,
    /// One registration per parked thread, including retained object IDs.
    parked: HashMap<u32, Wait>,
    /// Successful poll already consumed/dequeued its lock registration.
    completed: HashSet<u32>,
}

impl SyncState {
    /// Wakes up to `count` threads parked on `key` (all for `usize::MAX`).
    pub fn wake(&mut self, key: u128, count: usize) {
        if let Some(q) = self.waiters.get_mut(&key) {
            for _ in 0..count {
                match q.pop_front() {
                    Some(tid) => {
                        self.woken.insert(tid);
                    }
                    None => break,
                }
            }
            if q.is_empty() {
                self.waiters.remove(&key);
            }
        }
    }

    /// Forgets `tid`'s address wait (it timed out or its thread ended).
    fn cancel(&mut self, key: u128, tid: u32) {
        if let Some(q) = self.waiters.get_mut(&key) {
            q.retain(|&t| t != tid);
            if q.is_empty() {
                self.waiters.remove(&key);
            }
        }
        self.woken.remove(&tid);
    }
}

/// Records that `tid` parks on `wait` (queues address waiters).
pub fn on_block(p: &mut Proc, tid: u32, wait: &Wait) -> Result<(), SyncError> {
    if p.sync.parked.contains_key(&tid) {
        return Err(SyncError::Invalid("thread already has a registered wait"));
    }
    match wait {
        Wait::Objects { objs, all, .. } => {
            validate_objects(p, objs, *all)?;
            p.objects.retain_many(objs).map_err(SyncError::Invalid)?;
        }
        Wait::Address { key, .. } => {
            p.sync.woken.remove(&tid);
            p.sync.waiters.entry(*key).or_default().push_back(tid);
        }
        Wait::CritSec { addr } => {
            let n = p
                .sync
                .cs_waiters
                .get(addr)
                .copied()
                .unwrap_or(0)
                .checked_add(1)
                .ok_or(SyncError::Invalid("critical-section waiter overflow"))?;
            update_cs_waiters(p, *addr, n)?;
        }
        Wait::Srw {
            addr,
            exclusive: true,
        } => {
            let mut state = srw_state(p, *addr)?;
            state.waiting_exclusive = state
                .waiting_exclusive
                .checked_add(1)
                .ok_or(SyncError::Invalid("SRW waiter overflow"))?;
            commit_srw(p, *addr, state)?;
        }
        _ => {}
    }
    p.sync.parked.insert(tid, wait.clone());
    p.sync.completed.remove(&tid);
    Ok(())
}

/// Releases a registered wait after completion or cancellation. Repeated
/// cleanup is harmless; a different wait cannot cancel this thread's entry.
pub fn on_cancel(p: &mut Proc, tid: u32, wait: &Wait) -> Result<(), SyncError> {
    match p.sync.parked.get(&tid) {
        None => return Ok(()),
        Some(registered) if registered != wait => {
            return Err(SyncError::Invalid(
                "wait cancellation registration mismatch",
            ));
        }
        _ => {}
    }
    if p.sync.completed.contains(&tid) {
        if let Some(Wait::Objects { objs, .. }) = p.sync.parked.remove(&tid) {
            for obj in objs {
                p.objects.release(obj);
            }
        } else {
            p.sync.parked.remove(&tid);
        }
        p.sync.completed.remove(&tid);
        return Ok(());
    }
    match wait {
        Wait::Objects { .. } => {
            if let Some(Wait::Objects { objs, .. }) = p.sync.parked.get(&tid) {
                for obj in objs.clone() {
                    p.objects.release(obj);
                }
            }
        }
        Wait::Address { key, .. } => p.sync.cancel(*key, tid),
        Wait::CritSec { addr } => {
            let n = p
                .sync
                .cs_waiters
                .get(addr)
                .copied()
                .unwrap_or(0)
                .checked_sub(1)
                .ok_or(SyncError::Invalid("unregistered critical-section wait"))?;
            update_cs_waiters(p, *addr, n)?;
        }
        Wait::Srw {
            addr,
            exclusive: true,
        } => {
            let mut state = srw_state(p, *addr)?;
            state.waiting_exclusive = state
                .waiting_exclusive
                .checked_sub(1)
                .ok_or(SyncError::Invalid("unregistered SRW wait"))?;
            commit_srw(p, *addr, state)?;
        }
        _ => {}
    }
    p.sync.parked.remove(&tid);
    Ok(())
}

/// Process termination drops every wait pin without touching obsolete guest
/// lock storage. Ownership and queues cease to exist with the process; the
/// retained address space is diagnostic state, not a live lock protocol.
pub fn on_process_exit(p: &mut Proc) {
    let state = std::mem::take(&mut p.sync);
    for wait in state.parked.into_values() {
        if let Wait::Objects { objs, .. } = wait {
            for obj in objs {
                p.objects.release(obj);
            }
        }
    }
}

/// Retires other threads' parked waits before normal process-detach callbacks.
/// The selected thread and live lock ownership/initialization remain usable
/// until final shutdown. In particular, retirement cannot write guest lock
/// storage: a peer may have waited on an address that is now inaccessible.
///
/// The validation pass precedes all mutation, so a corrupt host registration
/// cannot partially release object pins or lock wait counts. A later live SRW
/// access accepts only the exact old word left by this operation; its first
/// successful write publishes the new count. Complexity is O(P + L) time and
/// O(P + L) auxiliary space for P peer registrations and L touched lock keys.
pub fn on_normal_process_exit(p: &mut Proc, caller_tid: u32) -> Result<(), SyncError> {
    let peers: Vec<(u32, Wait)> = p
        .sync
        .parked
        .iter()
        .filter(|(tid, _)| **tid != caller_tid)
        .map(|(&tid, wait)| (tid, wait.clone()))
        .collect();
    let mut cs_counts = HashMap::<u64, u32>::new();
    let mut srw_counts = HashMap::<u64, u32>::new();
    for (tid, wait) in &peers {
        // A successful poll already consumed a lock waiter count; only its
        // retained registration/pin remains until cancellation.
        if p.sync.completed.contains(tid) {
            continue;
        }
        match wait {
            Wait::CritSec { addr } => {
                let count = cs_counts.entry(*addr).or_default();
                *count = count.checked_add(1).ok_or(SyncError::Invalid(
                    "critical-section retirement count overflow",
                ))?;
            }
            Wait::Srw {
                addr,
                exclusive: true,
            } => {
                let count = srw_counts.entry(*addr).or_default();
                *count = count
                    .checked_add(1)
                    .ok_or(SyncError::Invalid("SRW retirement count overflow"))?;
            }
            _ => {}
        }
    }
    for (&addr, &count) in &cs_counts {
        if p.sync.cs_waiters.get(&addr).copied().unwrap_or(0) < count {
            return Err(SyncError::Invalid(
                "unregistered critical-section exit wait",
            ));
        }
    }
    let mut srw_updates = Vec::with_capacity(srw_counts.len());
    for (&addr, &count) in &srw_counts {
        let old_state = p
            .sync
            .srw
            .get(&addr)
            .ok_or(SyncError::Invalid("unregistered SRW exit wait"))?;
        let mut state = old_state.clone();
        state.waiting_exclusive = state
            .waiting_exclusive
            .checked_sub(count)
            .ok_or(SyncError::Invalid("unregistered SRW exit wait"))?;
        let old_word = srw_word(p, old_state)?;
        srw_updates.push((addr, state, old_word));
    }

    for (tid, wait) in peers {
        p.sync.parked.remove(&tid);
        p.sync.completed.remove(&tid);
        p.sync.woken.remove(&tid);
        match wait {
            Wait::Objects { objs, .. } => {
                for obj in objs {
                    p.objects.release(obj);
                }
            }
            Wait::Address { key, .. } => p.sync.cancel(key, tid),
            _ => {}
        }
    }
    for (addr, count) in cs_counts {
        let remaining = p.sync.cs_waiters[&addr] - count;
        set_cs_waiters(p, addr, remaining);
    }
    for (addr, state, old_word) in srw_updates {
        if state.exclusive.is_none() && state.shared.is_empty() && state.waiting_exclusive == 0 {
            p.sync.srw.remove(&addr);
        } else {
            p.sync.srw.insert(addr, state);
        }
        p.sync.retired_srw_words.insert(addr, old_word);
    }
    Ok(())
}

fn expired(deadline: Option<Instant>, now: Instant) -> bool {
    deadline.is_some_and(|d| now >= d)
}

/// Whether object `id` is signaled for thread `tid`.
fn signaled(p: &Proc, id: ObjId, tid: u32) -> bool {
    match p.objects.obj(id) {
        Some(Object::Event { signaled, .. }) => *signaled != 0,
        Some(Object::Timer { signaled, .. }) => *signaled,
        Some(Object::IrTimer { signaled, .. }) => *signaled,
        Some(Object::WaitCompletionPacket { signaled }) => *signaled,
        Some(Object::Mutex { owner, .. }) => owner.is_none() || *owner == Some(tid),
        Some(Object::Semaphore { count, .. }) => *count > 0,
        Some(Object::Thread { exit_code, .. }) | Some(Object::Process { exit_code, .. }) => {
            exit_code.is_some()
        }
        Some(Object::CompletionPort { queue, .. }) => !queue.is_empty(),
        // Files and console handles are signaled when no I/O is pending,
        // which is always here (I/O completes synchronously).
        Some(Object::File(_) | Object::Console(_) | Object::Null | Object::Pipe { .. }) => true,
        Some(
            Object::Mapping { .. }
            | Object::ImageSection(_)
            | Object::DataSection(_)
            | Object::WorkerFactory { .. }
            | Object::EtwRegistration { .. }
            | Object::SchedulerSharedData { .. }
            | Object::LpcPort(_)
            | Object::Key(_)
            | Object::Directory(_)
            | Object::SymbolicLink(_)
            | Object::PrimaryToken
            | Object::Opaque(_),
        )
        | None => false,
    }
}

/// Consumes a signaled object for `tid`; true if a mutex was abandoned.
fn consume(p: &mut Proc, id: ObjId, tid: u32) -> bool {
    match p.objects.obj_mut(id) {
        Some(Object::Event { manual, signaled }) if !*manual => {
            *signaled = 0;
            false
        }
        Some(Object::Timer {
            manual, signaled, ..
        }) if !*manual => {
            *signaled = false;
            false
        }
        Some(Object::IrTimer {
            attributes,
            signaled,
            ..
        }) if *attributes & 0x8000_0000 == 0 => {
            *signaled = false;
            false
        }
        Some(Object::Mutex {
            owner,
            count,
            abandoned,
        }) => {
            *owner = Some(tid);
            *count += 1;
            std::mem::take(abandoned)
        }
        Some(Object::Semaphore { count, .. }) => {
            *count -= 1;
            false
        }
        _ => false,
    }
}

/// Checks the complete set before consuming anything. Public builders also
/// validate handles/access rights. Only wait-all forbids duplicate aliases.
fn validate_objects(p: &Proc, objs: &[ObjId], all: bool) -> Result<(), SyncError> {
    if objs.is_empty() || objs.len() > 64 {
        return Err(SyncError::Invalid("invalid object wait count"));
    }
    let mut distinct = HashSet::with_capacity(objs.len());
    for &id in objs {
        if !distinct.insert(id) && all {
            return Err(SyncError::Invalid("duplicate object in wait set"));
        }
        let object = p
            .objects
            .obj(id)
            .ok_or(SyncError::Invalid("wait object disappeared"))?;
        if let Object::Mutex { owner, count, .. } = object {
            if owner.is_none() != (*count == 0) {
                return Err(SyncError::Invalid("corrupt mutex ownership/recursion"));
            }
        }
    }
    Ok(())
}

fn validate_consumption(p: &Proc, id: ObjId) -> Result<(), SyncError> {
    if let Some(Object::Mutex { count, .. }) = p.objects.obj(id) {
        count
            .checked_add(1)
            .ok_or(SyncError::Invalid("mutex recursion overflow"))?;
    }
    Ok(())
}

/// Satisfies an object wait now if possible: the wait status, or `None`.
/// Wait-all errors cannot partially consume earlier signaled objects. Public
/// Microsoft docs permit the whole abandoned-status range for wait-all; this
/// profile returns its base, not a claimed native abandoned-mutex index.
pub fn try_objects(
    p: &mut Proc,
    tid: u32,
    objs: &[ObjId],
    all: bool,
) -> Result<Option<u64>, SyncError> {
    pump_wait_packets(p)?;
    validate_objects(p, objs, all)?;
    if all {
        if objs.iter().all(|&o| signaled(p, o, tid)) {
            for &id in objs {
                validate_consumption(p, id)?;
            }
            let abandoned = objs.iter().fold(false, |a, &o| consume(p, o, tid) | a);
            return Ok(Some(if abandoned { WAIT_ABANDONED_0 } else { 0 }));
        }
        return Ok(None);
    }
    let Some(i) = objs.iter().position(|&o| signaled(p, o, tid)) else {
        return Ok(None);
    };
    validate_consumption(p, objs[i])?;
    let abandoned = consume(p, objs[i], tid);
    Ok(Some(
        if abandoned { WAIT_ABANDONED_0 } else { 0 } + i as u64,
    ))
}

/// Polls `tid`'s wait at `now`: its completion status, or `None` to keep
/// waiting. `apc_pending` reports queued user APCs for alertable waits.
pub fn poll(
    p: &mut Proc,
    tid: u32,
    wait: &Wait,
    now: Instant,
    apc_pending: bool,
) -> Result<Option<u64>, SyncError> {
    if p.sync.completed.contains(&tid) {
        return Err(SyncError::Invalid(
            "completed wait must be cleaned up before polling",
        ));
    }
    if p.sync
        .parked
        .get(&tid)
        .is_some_and(|registered| registered != wait)
    {
        return Err(SyncError::Invalid("wait poll registration mismatch"));
    }
    let result = poll_inner(p, tid, wait, now, apc_pending)?;
    if result.is_some() && p.sync.parked.contains_key(&tid) {
        p.sync.completed.insert(tid);
    }
    Ok(result)
}

fn poll_inner(
    p: &mut Proc,
    tid: u32,
    wait: &Wait,
    now: Instant,
    apc_pending: bool,
) -> Result<Option<u64>, SyncError> {
    Ok(match wait {
        Wait::Objects {
            objs,
            all,
            deadline,
            alertable,
        } => {
            if let Some(s) = try_objects(p, tid, objs, *all)? {
                return Ok(Some(s));
            }
            if *alertable && apc_pending {
                return Ok(Some(WAIT_IO_COMPLETION));
            }
            expired(*deadline, now).then_some(WAIT_TIMEOUT)
        }
        Wait::Sleep {
            deadline,
            alertable,
        } => {
            if *alertable && apc_pending {
                return Ok(Some(WAIT_IO_COMPLETION));
            }
            expired(*deadline, now).then_some(0)
        }
        Wait::Address { key, deadline } => {
            if p.sync.woken.remove(&tid) {
                return Ok(Some(u64::from(STATUS_SUCCESS)));
            }
            if expired(*deadline, now) {
                p.sync.cancel(*key, tid);
                return Ok(Some(u64::from(STATUS_TIMEOUT)));
            }
            None
        }
        Wait::CritSec { addr } => {
            let n = p
                .sync
                .cs_waiters
                .get(addr)
                .copied()
                .unwrap_or(0)
                .checked_sub(1)
                .ok_or(SyncError::Invalid("unregistered critical-section poll"))?;
            if cs_acquire(p, *addr, tid, n)? {
                Some(0)
            } else {
                None
            }
        }
        Wait::Srw { addr, exclusive } => {
            let mut s = srw_state(p, *addr)?;
            let ok = if *exclusive {
                s.exclusive.is_none() && s.shared.is_empty()
            } else {
                s.exclusive.is_none() && s.waiting_exclusive == 0
            };
            if !ok {
                return Ok(None);
            }
            if *exclusive {
                s.waiting_exclusive = s
                    .waiting_exclusive
                    .checked_sub(1)
                    .ok_or(SyncError::Invalid("unregistered SRW poll"))?;
                s.exclusive = Some(tid);
            } else {
                if !s.shared.insert(tid) {
                    return Err(SyncError::Invalid("recursive shared SRW acquisition"));
                }
            }
            commit_srw(p, *addr, s)?;
            Some(0)
        }
    })
}

// ------------------------------------------------------ critical sections

/// `CRITICAL_SECTION` field offsets: (LockCount, RecursionCount,
/// OwningThread) — (4, 8, 0xC) on x86, (8, 0xC, 0x10) on 64-bit
/// (winnt.h, verified).
fn cs_fields(p: &Proc) -> (u64, u64, u64) {
    if p.arch.is64() {
        (8, 0xC, 0x10)
    } else {
        (4, 8, 0xC)
    }
}

/// Validated storage extent and natural pointer alignment. Misuse diagnostics
/// are policy; native behavior for malformed objects is not an oracle here.
fn storage(p: &Proc, addr: u64, size: u64) -> Result<(), SyncError> {
    if addr == 0 || addr % p.arch.ptr_size() != 0 || addr.checked_add(size).is_none() {
        return Err(SyncError::Invalid(
            "unaligned/null/overflowing synchronization storage",
        ));
    }
    if !p.arch.is64() && addr.checked_add(size).is_none_or(|end| end > 1 << 32) {
        return Err(SyncError::Invalid(
            "synchronization storage exceeds guest pointer width",
        ));
    }
    Ok(())
}

fn cs_size(p: &Proc) -> usize {
    if p.arch.is64() { 0x28 } else { 0x18 }
}
fn get32(bytes: &[u8], at: u64) -> u32 {
    u32::from_le_bytes(bytes[at as usize..at as usize + 4].try_into().unwrap())
}
fn getptr(bytes: &[u8], at: u64, size: u64) -> u64 {
    let mut value = [0; 8];
    value[..size as usize].copy_from_slice(&bytes[at as usize..(at + size) as usize]);
    u64::from_le_bytes(value)
}
fn put32(bytes: &mut [u8], at: u64, value: u32) {
    bytes[at as usize..at as usize + 4].copy_from_slice(&value.to_le_bytes());
}
fn putptr(bytes: &mut [u8], at: u64, size: u64, value: u64) {
    bytes[at as usize..(at + size) as usize].copy_from_slice(&value.to_le_bytes()[..size as usize]);
}

fn cs_image(p: &Proc, addr: u64) -> Result<Vec<u8>, SyncError> {
    storage(p, addr, cs_size(p) as u64)?;
    if !p.sync.initialized_cs.contains(&addr) {
        return Err(SyncError::Invalid("uninitialized/deleted critical section"));
    }
    let bytes = p.space.bytes(addr, cs_size(p))?;
    let (_, rec, owner) = cs_fields(p);
    let recursion = get32(&bytes, rec);
    let owner = getptr(&bytes, owner, p.arch.ptr_size());
    if (owner == 0) != (recursion == 0) || recursion > i32::MAX as u32 || owner > u32::MAX as u64 {
        return Err(SyncError::Invalid(
            "corrupt critical-section owner/recursion",
        ));
    }
    Ok(bytes)
}

fn cs_word(bytes: &mut [u8], p: &Proc, waiters: u32) -> Result<(), SyncError> {
    let (lock, _, owner) = cs_fields(p);
    let count = if getptr(bytes, owner, p.arch.ptr_size()) == 0 {
        -1i64
    } else {
        -2i64 - 4 * i64::from(waiters)
    };
    let count = i32::try_from(count)
        .map_err(|_| SyncError::Invalid("critical-section waiter encoding overflow"))?;
    put32(bytes, lock, count as u32);
    Ok(())
}

fn set_cs_waiters(p: &mut Proc, addr: u64, n: u32) {
    if n == 0 {
        p.sync.cs_waiters.remove(&addr);
    } else {
        p.sync.cs_waiters.insert(addr, n);
    }
}

fn update_cs_waiters(p: &mut Proc, addr: u64, n: u32) -> Result<(), SyncError> {
    let mut bytes = cs_image(p, addr)?;
    cs_word(&mut bytes, p, n)?;
    p.space.wr(addr, &bytes)?;
    set_cs_waiters(p, addr, n);
    Ok(())
}

fn cs_acquire(p: &mut Proc, addr: u64, tid: u32, waiters: u32) -> Result<bool, SyncError> {
    if tid == 0 {
        return Err(SyncError::Invalid("zero critical-section thread ID"));
    }
    let mut bytes = cs_image(p, addr)?;
    let (_, rec, owner) = cs_fields(p);
    let current = getptr(&bytes, owner, p.arch.ptr_size());
    if current != 0 && current != u64::from(tid) {
        return Ok(false);
    }
    let count = if current == 0 {
        1
    } else {
        get32(&bytes, rec)
            .checked_add(1)
            .filter(|n| *n <= i32::MAX as u32)
            .ok_or(SyncError::Invalid("critical-section recursion overflow"))?
    };
    putptr(&mut bytes, owner, p.arch.ptr_size(), tid.into());
    put32(&mut bytes, rec, count);
    cs_word(&mut bytes, p, waiters)?;
    p.space.wr(addr, &bytes)?;
    set_cs_waiters(p, addr, waiters);
    Ok(true)
}

pub fn cs_try_enter(p: &mut Proc, addr: u64, tid: u32) -> Result<bool, SyncError> {
    let waiters = p.sync.cs_waiters.get(&addr).copied().unwrap_or(0);
    cs_acquire(p, addr, tid, waiters)
}

pub fn cs_leave(p: &mut Proc, addr: u64, tid: u32) -> Result<bool, SyncError> {
    let mut bytes = cs_image(p, addr)?;
    let (_, rec, owner) = cs_fields(p);
    if tid == 0 || getptr(&bytes, owner, p.arch.ptr_size()) != u64::from(tid) {
        return Ok(false);
    }
    let count = get32(&bytes, rec)
        .checked_sub(1)
        .ok_or(SyncError::Invalid("critical-section recursion underflow"))?;
    put32(&mut bytes, rec, count);
    if count == 0 {
        putptr(&mut bytes, owner, p.arch.ptr_size(), 0);
    }
    cs_word(
        &mut bytes,
        p,
        p.sync.cs_waiters.get(&addr).copied().unwrap_or(0),
    )?;
    p.space.wr(addr, &bytes)?;
    Ok(true)
}

pub fn cs_recursion(p: &Proc, addr: u64, tid: u32) -> Result<u32, SyncError> {
    let bytes = cs_image(p, addr)?;
    let (_, rec, owner) = cs_fields(p);
    if tid == 0 || getptr(&bytes, owner, p.arch.ptr_size()) != u64::from(tid) {
        return Err(SyncError::Invalid("critical section not owned by caller"));
    }
    Ok(get32(&bytes, rec))
}

pub fn cs_init(p: &mut Proc, addr: u64, spin: u64) -> Result<(), SyncError> {
    storage(p, addr, cs_size(p) as u64)?;
    if p.sync.initialized_cs.contains(&addr) {
        return Err(SyncError::Invalid(
            "critical section reinitialization without delete",
        ));
    }
    let mut bytes = vec![0u8; cs_size(p)];
    putptr(&mut bytes, 0, p.arch.ptr_size(), p.arch.ptr(u64::MAX));
    put32(&mut bytes, cs_fields(p).0, u32::MAX);
    putptr(
        &mut bytes,
        if p.arch.is64() { 0x20 } else { 0x14 },
        p.arch.ptr_size(),
        // The current Windows processor profile exposes one processor.
        // Microsoft specifies a zero effective spin count for that profile.
        {
            let _ = spin;
            0
        },
    );
    p.space.wr(addr, &bytes)?;
    p.sync.initialized_cs.insert(addr);
    Ok(())
}

pub fn cs_delete(p: &mut Proc, addr: u64) -> Result<(), SyncError> {
    let bytes = cs_image(p, addr)?;
    if getptr(&bytes, cs_fields(p).2, p.arch.ptr_size()) != 0
        || p.sync.cs_waiters.contains_key(&addr)
    {
        return Err(SyncError::Invalid("deleting active critical section"));
    }
    p.space.wr(addr, &vec![0; bytes.len()])?;
    p.sync.initialized_cs.remove(&addr);
    Ok(())
}

pub fn cs_spin(p: &mut Proc, addr: u64, spin: u64) -> Result<u64, SyncError> {
    let mut bytes = cs_image(p, addr)?;
    let at = if p.arch.is64() { 0x20 } else { 0x14 };
    let old = getptr(&bytes, at, p.arch.ptr_size());
    let _ = spin;
    putptr(&mut bytes, at, p.arch.ptr_size(), 0);
    // Normal process exit can retire peer waiters without touching obsolete
    // guest storage; this live mutation publishes the current count.
    cs_word(
        &mut bytes,
        p,
        p.sync.cs_waiters.get(&addr).copied().unwrap_or(0),
    )?;
    p.space.wr(addr, &bytes)?;
    Ok(old)
}

fn srw_word(p: &Proc, s: &SrwState) -> Result<u64, SyncError> {
    let shared =
        u64::try_from(s.shared.len()).map_err(|_| SyncError::Invalid("SRW reader overflow"))?;
    if shared > p.arch.ptr(u64::MAX) >> 4 {
        return Err(SyncError::Invalid("SRW reader encoding overflow"));
    }
    Ok(if s.exclusive.is_some() {
        1
    } else if shared > 0 {
        shared << 4 | 1
    } else {
        0
    } | if s.waiting_exclusive > 0 { 2 } else { 0 })
}

fn srw_state(p: &Proc, addr: u64) -> Result<SrwState, SyncError> {
    storage(p, addr, p.arch.ptr_size())?;
    let s = p.sync.srw.get(&addr).cloned().unwrap_or_default();
    let word = p.space.ptr(addr, p.arch.ptr_size())?;
    if word != srw_word(p, &s)? && p.sync.retired_srw_words.get(&addr).copied() != Some(word) {
        return Err(SyncError::Invalid("modified/uninitialized SRW lock word"));
    }
    Ok(s)
}

fn commit_srw(p: &mut Proc, addr: u64, s: SrwState) -> Result<(), SyncError> {
    p.space.wptr(addr, p.arch.ptr_size(), srw_word(p, &s)?)?;
    p.sync.retired_srw_words.remove(&addr);
    if s.exclusive.is_none() && s.shared.is_empty() && s.waiting_exclusive == 0 {
        p.sync.srw.remove(&addr);
    } else {
        p.sync.srw.insert(addr, s);
    }
    Ok(())
}

pub fn srw_init(p: &mut Proc, addr: u64) -> Result<(), SyncError> {
    storage(p, addr, p.arch.ptr_size())?;
    if p.sync.srw.contains_key(&addr) {
        return Err(SyncError::Invalid("reinitializing active SRW lock"));
    }
    p.space.wptr(addr, p.arch.ptr_size(), 0)?;
    p.sync.retired_srw_words.remove(&addr);
    Ok(())
}

pub fn srw_try(p: &mut Proc, addr: u64, tid: u32, exclusive: bool) -> Result<bool, SyncError> {
    let mut s = srw_state(p, addr)?;
    if tid == 0 {
        return Err(SyncError::Invalid("zero SRW thread ID"));
    }
    if s.exclusive == Some(tid) || s.shared.contains(&tid) {
        return Ok(false);
    }
    if s.exclusive.is_some()
        || (exclusive && !s.shared.is_empty())
        || (!exclusive && s.waiting_exclusive > 0)
    {
        return Ok(false);
    }
    if exclusive {
        s.exclusive = Some(tid);
    } else {
        s.shared.insert(tid);
    }
    commit_srw(p, addr, s)?;
    Ok(true)
}

pub fn srw_release(p: &mut Proc, addr: u64, tid: u32, exclusive: bool) -> Result<(), SyncError> {
    let mut s = srw_state(p, addr)?;
    if exclusive {
        if s.exclusive != Some(tid) {
            return Err(SyncError::Invalid("exclusive SRW release by non-owner"));
        }
        s.exclusive = None;
    } else if !s.shared.remove(&tid) {
        return Err(SyncError::Invalid("shared SRW release by non-owner"));
    }
    commit_srw(p, addr, s)
}

pub fn srw_held(p: &Proc, addr: u64, tid: u32) -> Result<Option<bool>, SyncError> {
    let s = srw_state(p, addr)?;
    if s.exclusive == Some(tid) {
        Ok(Some(true))
    } else if s.shared.contains(&tid) {
        Ok(Some(false))
    } else {
        Ok(None)
    }
}

pub fn cv_init(p: &mut Proc, addr: u64) -> Result<(), SyncError> {
    storage(p, addr, p.arch.ptr_size())?;
    if p.sync
        .waiters
        .contains_key(&(u128::from(addr) | CONDVAR_KEY))
    {
        return Err(SyncError::Invalid(
            "reinitializing active condition variable",
        ));
    }
    p.space.wptr(addr, p.arch.ptr_size(), 0)?;
    Ok(())
}

pub fn cv_check(p: &Proc, addr: u64) -> Result<(), SyncError> {
    storage(p, addr, p.arch.ptr_size())?;
    if p.space.ptr(addr, p.arch.ptr_size())? != 0 {
        return Err(SyncError::Invalid(
            "modified/uninitialized condition variable",
        ));
    }
    p.space
        .probe(
            addr,
            p.arch.ptr_size() as usize,
            crate::error::MemoryAccessKind::Write,
        )
        .map_err(|f| {
            SyncError::Fault(MemFault {
                addr: f.address,
                write: true,
            })
        })?;
    Ok(())
}

/// `TEB` offset of `LastErrorValue`, used by waits that report errors.
pub fn last_error_offset(p: &Proc) -> u64 {
    offsets(p.arch).teb_last_error
}

