            t: &mut t,
            api,
            entry_pc: 0,
            entry_sp: sp,
            ret_addr: 0,
            cursor: sp,
        };
        assert!(matches!(
            continue_context(&mut c).unwrap(),
            Flow::Ret(Value::Int(status)) if status == u64::from(STATUS_INVALID_PARAMETER)
        ));
        assert_eq!(RegContext::capture(&c.t.cpu).bytes(), old.bytes());
        saved.set_flags(RegContext::arch_flag(c.arch()) | INTEGER);
        saved.write(c.mem(), address).unwrap();
        assert!(matches!(continue_context(&mut c).unwrap(), Flow::Resume(_)));
        c.t.cpu.set_gpr(1, address + 1);
        assert!(matches!(
            continue_context(&mut c).unwrap(),
            Flow::Ret(Value::Int(status)) if status == u64::from(STATUS_INVALID_PARAMETER)
        ));
        c.t.cpu.set_gpr(1, address);
        c.t.cpu.set_gpr(2, 1);
        assert!(matches!(
            continue_context(&mut c),
            Err(ApiErr::Unimplemented(_))
        ));
        c.t.cpu.set_gpr(2, 0);
        c.t.cpu.set_gpr(1, u64::MAX - 15);
        assert!(matches!(continue_context(&mut c), Err(ApiErr::Fault(_))));
    }
}

//! Measured no-impersonation thread-token opening, from build29683 captures.
use super::query::write_guard_result;
use crate::user::windows::arch::WinArch;
use crate::user::windows::hle::{ApiResult, Ctx, Flow};
use crate::user::windows::memory::Mem;
use crate::user::windows::nt::status::*;
use crate::user::windows::objects::Object;

pub(super) fn open_thread(c: &mut Ctx) -> ApiResult {
    let result = checked(c);
    write_guard_result(c, result)
}
fn checked(c: &mut Ctx) -> ApiResult {
    let (handle, _desired, _self, output) = (c.ptr(0)?, c.u32(1)?, c.u32(2)?, c.ptr(3)?);
    let status = absent_thread_token(c, handle);
    if c.arch() == WinArch::X86 && output != 0 {
        // Captured WoW64 initializes the private native handle to zero and
        // copies it back even on kernel failure. Copy faults override status;
        // writable guards consume once; read-only guards remain armed.
        // Its null-output test skips this caller copy entirely.
        c.mem().w32(output, 0)?;
    }
    Flow::ret(status.into())
}
fn absent_thread_token(c: &Ctx, handle: u64) -> u32 {
    if handle == c.arch().ptr(u64::MAX) {
        return STATUS_OBJECT_TYPE_MISMATCH;
    }
    if handle != c.arch().ptr(u64::MAX - 1) {
        match c.p.objects.get(handle) {
            None => return STATUS_INVALID_HANDLE,
            Some(Object::Thread { .. }) => {
                // Captured current/local/ended threads accept either query
                // information or query-limited-information, including aliases.
                if c.p.objects.access(handle).unwrap_or(0) & 0x840 == 0 {
                    return STATUS_ACCESS_DENIED;
                }
            }
            Some(_) => return STATUS_OBJECT_TYPE_MISMATCH,
        }
    }
    // This kernel personality has no thread-token attachment service.
    // Its new and ended threads have no impersonation token.
    // NtSetInformationThread class5 and impersonation-producing services
    // remain explicit unsupported boundaries, rather than changing this state.
    STATUS_NO_TOKEN
}

//! Captured primary-token properties with measured caller-probe ordering.
use super::query::{guard_result, probe_write};
use crate::user::windows::hle::{ApiResult, Ctx, Flow};
use crate::user::windows::memory::Mem;
use crate::user::windows::nt::status::*;
use crate::user::windows::objects::Object;

pub(super) fn information(c: &mut Ctx) -> ApiResult {
    let result = checked(c);
    guard_result(c, result)
}

fn checked(c: &mut Ctx) -> ApiResult {
    let (token, class, output, length, returned) =
        (c.ptr(0)?, c.u32(1)?, c.ptr(2)?, c.u32(3)?, c.ptr(4)?);
    if class != 29 {
        return Err(c.unsupported(format!("NtQueryInformationToken class {class}")));
    }
    // Both native64 and WoW64 probe the complete supplied span before token
    // validation. ReturnLength is mandatory and permits unaligned ULONG stores.
    // Do not reject a long span before visiting its first guarded page.
    if length != 0 {
        if output % 4 != 0 {
            return Flow::ret(STATUS_DATATYPE_MISALIGNMENT.into());
        }
        probe_write(c, output, length as usize)?;
    }
    probe_write(c, returned, 4)?;
    let process_token = c.arch().ptr(u64::MAX - 3);
    let thread_token = c.arch().ptr(u64::MAX - 4);
    let effective_token = c.arch().ptr(u64::MAX - 5);
    if token == thread_token {
        return Flow::ret(STATUS_NO_TOKEN.into());
    }
    if token != process_token && token != effective_token {
        if token == c.arch().ptr(u64::MAX) || token == c.arch().ptr(u64::MAX - 1) {
            return Flow::ret(STATUS_OBJECT_TYPE_MISMATCH.into());
        }
        match c.p.objects.get(token) {
            None => return Flow::ret(STATUS_INVALID_HANDLE.into()),
            Some(Object::PrimaryToken) => {
                if c.p.objects.access(token).unwrap_or(0) & 8 == 0 {
                    return Flow::ret(STATUS_ACCESS_DENIED.into());
                }
            }
            Some(Object::Opaque("Token")) => {
                return Err(c.unsupported("opaque token has no modeled primary subject"));
            }
            Some(_) => return Flow::ret(STATUS_OBJECT_TYPE_MISMATCH.into()),
        }
    }
    let Some(app_container) = c.p.objects.primary_token_app_container() else {
        return Err(c.unsupported("primary-token subject is not captured"));
    };
    // Native writes the required length before either short-buffer return or
    // successful data publication. Overlapping output therefore wins.
    c.mem().w32(returned, 4)?;
    if length < 4 {
        return Flow::ret(STATUS_BUFFER_TOO_SMALL.into());
    }
    c.mem().w32(output, u32::from(app_container))?;
    Flow::ret(STATUS_SUCCESS.into())
}

