    assert_eq!(t.cpu.sp(), sp);
    assert!(p.objects.get(u64::from(handle)).is_none());
    t.cpu.run(1);
    assert_eq!(t.cpu.pc(), return_pc);
    assert_eq!(t.cpu.sp(), sp + 8);
}

