        p.vm.allocate(None, PAGE_SIZE, mem::RESERVE | mem::COMMIT, prot::READWRITE)
            .unwrap()
            .0;
    p.space.wr(scratch, &[0xA5; 128]).unwrap();
    (process, t, scratch)
}

