            assert_eq!(p.space.u32(returned).unwrap(), 0xA5A5_A5A5);
            t.cpu.set_sp(sp);
            query_arguments(p, &mut t, 50, scratch, arch.ptr_size() as u32, returned);
            assert_eq!(dispatch_query(p, &mut t), Outcome::Continue);
            assert_eq!(t.cpu.gpr(0), 0);
            assert_eq!(p.space.u32(returned).unwrap(), arch.ptr_size() as u32);
            assert!(t.frames.is_empty());
        }
    }
}

#[test]
fn wow64_range_query_tracks_the_executable_large_address_aware_flag() {
    use crate::user::image::pe::IMAGE_FILE_LARGE_ADDRESS_AWARE;
    for large in [false, true] {
        let mut image =
            include_bytes!("../../../../../../tests/fixtures/user/windows/bin/x86/smoke.exe")
                .to_vec();
        let pe = u32::from_le_bytes(image[0x3c..0x40].try_into().unwrap()) as usize;
        let mut flags = u16::from_le_bytes(image[pe + 22..pe + 24].try_into().unwrap());
        if large {
            flags |= IMAGE_FILE_LARGE_ADDRESS_AWARE;
        } else {
            flags &= !IMAGE_FILE_LARGE_ADDRESS_AWARE;
        }
        image[pe + 22..pe + 24].copy_from_slice(&flags.to_le_bytes());
        let mut config = WindowsConfig::embedded("C:\\app\\range.exe", vec![], vec![], 0).unwrap();
        config.arena_bytes = (128 << 20) + 123; // Backing rounds down to 4 KiB.
        let mut process = super::super::super::WindowsProcess::spawn_image(config, image).unwrap();
        let p = process.state_mut();
        let module = p.modules.by_name("ntdll.dll").unwrap();
        p.modules.nt_services = Some((
            module,
            table(WinArch::X86, "NtQuerySystemInformation", 0x36),
        ));
        let tid = *p.threads.keys().next().unwrap();
        let mut t = p.threads.remove(&tid).unwrap();
        let sp = t.cpu.sp();
        let output = sp - 128;
        query_arguments(p, &mut t, 50, output, 4, output + 16);
        assert_eq!(dispatch_query(p, &mut t), Outcome::Continue);
        assert_eq!(t.cpu.gpr(0), 0);
        let expected = if large { 0xFFFF_0000 } else { 0x7FFF_0000 };
        assert_eq!(p.vm.high(), expected);
        assert_eq!(p.space.u32(output).unwrap(), expected as u32);
        assert_eq!(p.space.u32(output + 16).unwrap(), 4);
        t.cpu.set_sp(sp);
        query_arguments(p, &mut t, 0, output, 44, output + 96);
        assert_eq!(dispatch_query(p, &mut t), Outcome::Continue);
        assert_eq!(t.cpu.gpr(0), 0);
        assert_eq!(p.space.u32(output + 12).unwrap(), 32_768);
        assert_eq!(p.space.u32(output + 20).unwrap(), 32_767);
        assert_eq!(p.space.u32(output + 32).unwrap(), expected as u32 - 1);
        assert_eq!(p.space.u32(output + 96).unwrap(), 44);
    }
}

#[cfg(windows)]
#[test]
fn installed_native_range_query_executes_the_selected_leaf_and_actual_return() {
    use crate::user::windows::{
        loader::{self, SymRef},
        native::NativeRuntime,
    };
    let host_arch = if cfg!(target_arch = "aarch64") {
        WinArch::Arm64
    } else if cfg!(target_arch = "x86_64") {
        WinArch::X64
    } else {
        WinArch::X86
    };
    let mut arches = vec![host_arch];
    if host_arch != WinArch::X86 {
        arches.push(WinArch::X86);
    }
    for (arch, class) in arches
        .into_iter()
        .flat_map(|arch| [50u32, 0].map(|class| (arch, class)))
    {
        let runtime = NativeRuntime::select(arch).unwrap();
        let bytes = std::fs::read(runtime.dll("ntdll.dll").unwrap().unwrap()).unwrap();
        let (mut process, mut t, _) = terminal_fixture(arch);
        let p = process.state_mut();
        let mut config = (*p.cfg).clone();
        config.host_filesystem = false;
        config
            .supplied_dlls
            .insert("c:\\selected\\ntdll.dll".into(), bytes.into());
        p.cfg = Arc::new(config);
        let module = loader::load_dll(p, "C:\\selected\\ntdll.dll").unwrap();
        let entry = loader::lookup(
            p,
            module,
            &SymRef::Name(b"NtQuerySystemInformation".to_vec(), None),
        )
        .unwrap()
        .unwrap();
        let sp = t.cpu.sp();
        let output = sp - 128;
        let returned = output + 96;
        let length = if class == 0 {
            if arch == WinArch::X86 { 44 } else { 64 }
        } else {
            arch.ptr_size()
        };
        let resume = p.traps.callback_return();
        match arch {
            WinArch::X86 => {
                for (index, value) in [resume, u64::from(class), output, length, returned]
                    .into_iter()
                    .enumerate()
                {
                    p.space.w32(sp + index as u64 * 4, value as u32).unwrap();
                }
            }
            WinArch::X64 => {
                p.space.w64(sp, resume).unwrap();
                for (register, value) in [
                    (1, u64::from(class)),
                    (2, output),
                    (8, length),
                    (9, returned),
                ] {
                    t.cpu.set_gpr(register, value);
                }
            }
            WinArch::Arm64 => {
                for (register, value) in [
                    (0, u64::from(class)),
                    (1, output),
                    (2, length),
                    (3, returned),
                    (30, resume),
                ] {
                    t.cpu.set_gpr(register, value);
                }
            }
        }
        p.space.wr(output, &[0xA5; 104]).unwrap();
        t.cpu.set_pc(entry);
        let boundary = t.cpu.run(64);
        let outcome = handle_stop(p, &mut t, boundary);
        assert_eq!(outcome, Outcome::Continue, "{arch}");
        assert_eq!(t.cpu.gpr(0), 0);
        if class == 50 {
            assert_eq!(
                p.space.ptr(output, arch.ptr_size()).unwrap(),
                if arch == WinArch::X86 {
                    0x7FFF_0000
                } else {
                    0xFFFF_8000_0000_0000
                }
            );
        } else {
            assert_eq!(p.space.u32(output + 8).unwrap(), 4096);
            assert_eq!(p.space.u32(output + 12).unwrap(), 16_384);
            assert_eq!(
                p.space
                    .u8(output + if arch == WinArch::X86 { 40 } else { 56 })
                    .unwrap(),
                1
            );
            if arch == WinArch::X86 {
                assert_eq!(p.space.bytes(output + 41, 3).unwrap(), [0xA5; 3]);
            }
        }
        assert_eq!(p.space.u32(returned).unwrap(), length as u32);
        // Kernel dispatch resumes the installed DLL's own RET/RET imm16.
        t.cpu.run(8);
        assert_eq!(t.cpu.pc(), resume);
        assert_eq!(
            t.cpu.sp(),
            sp + match arch {
                WinArch::X86 => 20,
                WinArch::X64 => 8,
                WinArch::Arm64 => 0,
            }
        );
        assert!(t.frames.is_empty());
    }
}

//! Native token-query records, not expected values copied from the adapter.
use super::*;
use crate::user::windows::process::{WindowsConfig, WindowsProcess};

fn setup(arch: WinArch, laa: bool) -> (WindowsProcess, Thread, u64, [u64; 3]) {
    setup_runtime(arch, laa, false)
}

fn setup_runtime(
    arch: WinArch,
    laa: bool,
    native: bool,
) -> (WindowsProcess, Thread, u64, [u64; 3]) {
    let mut image = match arch {
        WinArch::X86 => {
            include_bytes!("../../../../../../../tests/fixtures/user/windows/bin/x86/smoke.exe")
                .to_vec()
        }
        WinArch::X64 => {
            include_bytes!("../../../../../../../tests/fixtures/user/windows/bin/x64/smoke.exe")
                .to_vec()
        }
        WinArch::Arm64 => {
            include_bytes!("../../../../../../../tests/fixtures/user/windows/bin/arm64/smoke.exe")
                .to_vec()
        }
    };
    if laa {
        let pe = u32::from_le_bytes(image[60..64].try_into().unwrap()) as usize;
        let flags = u16::from_le_bytes(image[pe + 22..pe + 24].try_into().unwrap()) | 0x20;
        image[pe + 22..pe + 24].copy_from_slice(&flags.to_le_bytes());
    }
    let mut cfg = WindowsConfig::embedded("C:\\token-query.exe", vec![], vec![], 4096).unwrap();
    cfg.arena_bytes = 64 << 20;
    cfg.native_libraries = native;
    let mut process = WindowsProcess::spawn_image(cfg, image).unwrap();
    let p = process.state_mut();
    let tid = *p.threads.keys().next().unwrap();
    let mut thread = p.threads.remove(&tid).unwrap();
    thread.attached = true;
    thread.main = false;
    if !native {
        let ntdll = p.modules.by_name("ntdll.dll").unwrap();
        p.modules.nt_services = Some((ntdll, table(arch, "NtQueryInformationToken", 0x21)));
        p.objects
            .select_wnf_catalog(crate::user::windows::wnf::tests::empty_subject_catalog(
                false,
            ));
    }
    let base =
        p.vm.allocate(
            None,
            PAGE_SIZE * 8,
            mem::RESERVE | mem::COMMIT,
            prot::READWRITE,
        )
        .unwrap()
        .0;
    let event = p.objects.create(Object::Event {
        manual: false,
        signaled: 0,
    });
    let event = u64::from(p.objects.open(event, false));
    let token = p.objects.create(Object::PrimaryToken);
    let query = u64::from(p.objects.open_access(token, false, 8).unwrap());
    let denied = u64::from(p.objects.open_access(token, false, 0).unwrap());
    (process, thread, base, [event, query, denied])
}

fn invoke(p: &mut Proc, thread: &mut Thread, args: &[u64]) -> Outcome {
    super::nls_tests::arguments(p, thread, args);
    if p.arch != WinArch::Arm64 {
        thread.cpu.set_gpr(0, 0x21);
    }
    if p.arch == WinArch::X86 {
        super::super::super::super::services::wow64(p, thread, 0x1234_0000)
    } else {
        handle_stop(p, thread, stop(p.arch, 0x21))
    }
}

fn handle(p: &Proc, kind: &str, handles: [u64; 3]) -> u64 {
    match kind {
        "primary" => p.arch.ptr(u64::MAX - 3),
        "thread-token" => p.arch.ptr(u64::MAX - 4),
        "effective" => p.arch.ptr(u64::MAX - 5),
        "null" => 0,
        "process" => p.arch.ptr(u64::MAX),
        "thread" => p.arch.ptr(u64::MAX - 1),
        "invalid" => 0xDEAD,
        "event" => handles[0],
        "real" => handles[1],
        "no-access" => handles[2],
        _ => panic!("unknown native handle role"),
    }
}

fn destinations(p: &mut Proc, base: u64, role: u32) -> (u64, u64) {
    p.vm.protect(base, PAGE_SIZE * 8, prot::READWRITE).unwrap();
    p.space
        .wr(base, &vec![0xA5; (PAGE_SIZE * 8) as usize])
        .unwrap();
    let mut output = base + PAGE_SIZE;
    let mut returned = base + PAGE_SIZE * 5;
    let mut protection = None;
    match role {
        0 | 25..=40 => {}
        1 => output = 0,
        2..=4 => output += u64::from(role - 1),
        5 => returned = 0,
        6..=8 => returned += u64::from(role - 5),
        9..=12 => {
            protection = Some((
                output,
                [
                    prot::NOACCESS,
                    prot::READONLY,
                    prot::READWRITE | prot::GUARD,
                    prot::READONLY | prot::GUARD,
                ][(role - 9) as usize],
            ))
        }
        13..=16 => {
            protection = Some((
                returned,
                [
                    prot::NOACCESS,
                    prot::READONLY,
                    prot::READWRITE | prot::GUARD,
                    prot::READONLY | prot::GUARD,
                ][(role - 13) as usize],
            ))
        }
        17 => returned = output,
        18 => returned = output + 1,
        19 | 24 => {
            output += PAGE_SIZE - if role == 19 { 2 } else { 4 };
            protection = Some((base + PAGE_SIZE * 2, prot::NOACCESS));
        }
        20 => {
            returned += PAGE_SIZE - 2;
            protection = Some((base + PAGE_SIZE * 6, prot::NOACCESS));
        }
        21 => {
            output = 0;
            returned = 0;
        }
        22 => {
            output = 1;
            returned = 0;
        }
        23 => {
            output = 0;
            returned += 1;
        }
        41 | 42 => {
            output = 0;
            protection = Some((
                returned,
                if role == 41 {
                    prot::READWRITE | prot::GUARD
                } else {
                    prot::READONLY | prot::GUARD
                },
            ));
        }
        _ => panic!("unknown native pointer role"),
    }
    if (25..=40).contains(&role) {
        let protections = [
            prot::NOACCESS,
            prot::READONLY,
            prot::READWRITE | prot::GUARD,
            prot::READONLY | prot::GUARD,
        ];
        let pair = (role - 25) as usize;
        p.vm.protect(output, PAGE_SIZE, protections[pair / 4])
            .unwrap();
        p.vm.protect(returned, PAGE_SIZE, protections[pair % 4])
            .unwrap();
    }
    if let Some((address, protect)) = protection {
        p.vm.protect(address, PAGE_SIZE, protect).unwrap();
    }
    (output, returned)
}

fn cells(p: &Proc, address: u64, expected: &str) {
    assert_eq!(expected.len(), 8);
    for (index, hex) in expected.as_bytes().chunks_exact(2).enumerate() {
        if hex != b"??" {
            let expected = u8::from_str_radix(std::str::from_utf8(hex).unwrap(), 16).unwrap();
            assert_eq!(
                p.space.u8(address + index as u64).unwrap(),
                expected,
                "cell {index}"
            );
        }
    }
}

#[test]
fn native_token_query_replays_all_7320_native_profile_rows() {
    let fixture: serde_json::Value = serde_json::from_str(include_str!(
        "../../../../../../../docs/specifications/windows/native-token-query/cases.json"
    ))
    .unwrap();
    let rows = fixture["cases"].as_array().unwrap();
    assert_eq!(rows.len(), 1830);
    for (arch, laa) in [
        (WinArch::Arm64, false),
        (WinArch::X64, false),
        (WinArch::X86, false),
        (WinArch::X86, true),
    ] {
        let (mut process, mut thread, base, handles) = setup(arch, laa);
        let p = process.state_mut();
        for (index, row) in rows.iter().enumerate() {
            let value = |name: &str| row[name].as_str().unwrap();
            let role: u32 = value("role").parse().unwrap();
            let (output, returned) = destinations(p, base, role);
            let token = handle(p, value("kind"), handles);
            let length = u32::from_str_radix(value("length"), 16).unwrap();
            let status = u32::from_str_radix(value("status"), 16).unwrap();
            let sp = thread.cpu.sp();
            let rng = p.rng;
            let count = p.objects.handle_count();
            assert_eq!(
                invoke(
                    p,
                    &mut thread,
                    &[token, 29, output, u64::from(length), returned]
                ),
                Outcome::Continue,
                "{arch}/{laa}/row{index}"
            );
            assert_eq!(
                thread.cpu.gpr(0),
                u64::from(status),
                "{arch}/{laa}/row{index}/{row}"
            );
            assert_eq!(
                thread.cpu.sp(),
                sp + if arch == WinArch::X86 { 4 } else { 0 }
            );
            thread.cpu.set_sp(sp);
            assert!(thread.frames.is_empty());
            assert_eq!(p.rng, rng);
            assert_eq!(p.objects.handle_count(), count);
            for (address, name) in [(output, "output-protect"), (returned, "returned-protect")] {
                if (base..base + PAGE_SIZE * 8).contains(&address) {
                    assert_eq!(
                        p.vm.query(address).unwrap().protect,
                        u32::from_str_radix(value(name), 16).unwrap(),
                        "{arch}/{laa}/row{index}/{name}"
                    );
                }
            }
            cells(p, output, value("output-bytes-cells"));
            cells(p, returned, value("return-bytes-cells"));
        }
    }
}

#[test]
fn native_token_query_reads_retained_false_true_and_missing_subject_state() {
    for arch in WinArch::ALL {
        let (mut process, mut thread, base, handles) = setup(arch, false);
        let p = process.state_mut();
        for flag in [false, true] {
            p.objects
                .select_wnf_catalog(crate::user::windows::wnf::tests::empty_subject_catalog(
                    flag,
                ));
            for kind in ["primary", "effective", "real"] {
                let (output, returned) = destinations(p, base, 0);
                let token = handle(p, kind, handles);
                let sp = thread.cpu.sp();
                assert_eq!(
                    invoke(p, &mut thread, &[token, 29, output, 8, returned]),
                    Outcome::Continue
                );
                thread.cpu.set_sp(sp);
                assert_eq!(thread.cpu.gpr(0), 0);
                assert_eq!(p.space.u32(output).unwrap(), u32::from(flag));
                assert_eq!(p.space.u32(returned).unwrap(), 4);
                assert_eq!(p.space.bytes(output + 4, 4).unwrap(), [0xA5; 4]);
            }
        }
        p.objects.select_wnf_catalog(Default::default());
        let (output, returned) = destinations(p, base, 0);
        let result = invoke(
            p,
            &mut thread,
            &[arch.ptr(u64::MAX - 3), 29, output, 4, returned],
        );
        assert_ne!(
            result,
            Outcome::Continue,
            "missing subject must not become a false flag"
        );
        assert_eq!(p.space.u32(output).unwrap(), 0xA5A5_A5A5);
        assert_eq!(p.space.u32(returned).unwrap(), 0xA5A5_A5A5);
    }
}

